"""Plain-language definitions shown on hover, focus and touch."""
DESCRIPTIONS = {
    "eye_tilt": "Угол от внутреннего к внешнему уголку глаза после поправки на наклон головы. Плюс означает, что внешний уголок выше. Ракурс и ошибка точек меняют результат.",
    "eye_aspect": "Ширина глаза между уголками, делённая на среднее расстояние между верхним и нижним веком. Чем больше число, тем уже видимое раскрытие относительно ширины. Прищур и моргание сильно влияют на показатель.",
    "brow_gap": "Расстояние между средними центрами точек брови и глаза, делённое на ширину контура лица. Это двумерное расстояние, а не глубина посадки глаз.",
    "brow_angle": "Наклон от внутреннего конца брови к внешнему с поправкой на наклон головы. Описывает направление размеченной брови, а не её густоту.",
    "brow_arch": "Максимальное отклонение точек брови от прямой между её концами, нормированное на длину этой прямой. Описывает изгиб видимого контура.",
    "intereye": "Расстояние между внутренними уголками глаз, делённое на ширину контура лица. Отличается от one-eye ratio: знаменатель здесь — ширина лица.",
    "eye_tilt_difference": "Абсолютная разница наклона левого и правого глаза на снимке. Она может возникать из-за ракурса или ошибки модели; это не доказательство анатомического дефекта.",
    "eye_aspect_difference": "Абсолютная разница отношений ширины к видимой высоте двух глаз. Может меняться из-за прищура, выражения лица и ошибки точек.",
    "jaw_width": "Отношение нижней ширины видимого контура к ширине лица. Точки не являются анатомическими gonion и zygion: строение кости по ним не определяется.",
    "lower_middle": "Длина от основания носа до подбородка, делённая на длину от переносицы до основания носа. Это выбранные сегменты, а не классические трети лица.",
    "width_height": "Ширина между крайними точками контура, делённая на высоту от переносицы до подбородка. Не эквивалентно анатомическому fWHR.",
    "asymmetry": "Среднее несовпадение пар точек после отражения относительно оси между глазами, нормированное на ширину лица. Показывает асимметрию проекции этого снимка, а не обязательно самого лица.",
    "eye_spacing": "Расстояние между внутренними уголками глаз, делённое на среднюю ширину двух глаз. Значение 1 означает промежуток примерно в один глаз.",
    "mouth_nose": "Ширина рта между уголками, делённая на ширину крыльев носа. Улыбка меняет ширину рта, поворот головы — обе видимые ширины.",
    "midface_pupils": "Межзрачковое расстояние, делённое на высоту от середины линии зрачков до верхней губы после выравнивания головы. Используются размеченные моделью центры зрачков. Это конкретное определение midface ratio, а не универсальный стандарт.",
}


def describe(key):
    if key in DESCRIPTIONS:
        return DESCRIPTIONS[key]
    return DESCRIPTIONS.get(key.rsplit("_",1)[0],"Двумерное измерение по предсказанным ориентирам. Формула и точки приведены в карточке.")
